/// All 5 compiled NIST MEOS records.
pub static MULTIPARAMETER_RECORDS: [&MultiparameterRecord; 5] = [
    &C3_RECORD,
    &R134A_RECORD,
    &NORMAL_H2_RECORD,
    &ORTHO_H2_RECORD,
    &PARA_H2_RECORD,
];

/// Lookup NIST Multiparameter record by fluid identifier.
pub fn lookup_multiparameter_record(ident: &str) -> Option<&'static MultiparameterRecord> {
    let id_up = ident.trim().to_ascii_uppercase();
    MULTIPARAMETER_RECORDS.iter().copied().find(|r| {
        r.ident.eq_ignore_ascii_case(&id_up)
            || (id_up == "PROPANE" && r.ident == "C3")
            || (id_up == "H2" && r.ident == "N-H2")
    })
}
